const projects = [
{id:'glasswing',name:'Glasswing International',type:'Volunteer platform & automation',category:['platforms','automation'],theme:'glasswing',headline:'From first sign-up to ready-to-serve.',summary:'A connected journey for volunteer onboarding, training and program readiness, with a bot for notifications and follow-ups.',role:'Full Stack Developer / Automation Engineer',context:'Glasswing needs to follow volunteers as they complete onboarding and training, then become ready to participate in its programs.',contribution:'Built a volunteer management platform covering personal information, introductory content, training participation and project selection. Developed a bot to support notifications and follow-up workflows.',detail:'The platform brings volunteer progress and operational follow-up into a shared workflow, giving teams a place to track preparation for program participation.',stack:['TypeScript','Angular','Python','SQL','APIs'],image:'assets/glasswing-training.jpeg',secondImage:'assets/glasswing-login.jpeg',caption:'Supplied screenshots of the volunteer onboarding and sign-in experience.'},
{id:'lonelyplanet',name:'Lonely Planet',type:'Content engineering · Red Ventures',category:['automation'],theme:'lonely',headline:'Behind the stories. At content scale.',summary:'TypeScript automation and Contentful workflows supporting a global travel content platform.',role:'Senior TypeScript Engineer / Contentful Platform Developer',context:'Large content platforms require repeatable migration, validation and publishing workflows across environments.',contribution:'As part of the Lonely Planet / Red Ventures engineering experience, build TypeScript and Node.js automation for content migration, validation, publishing, deduplication and quality. Contributed to workflows involving approximately 199,000 point-of-interest entries.',detail:'Integrate REST, GraphQL, webhooks and content APIs, and support event-driven processes and GitHub Actions / AWS deployment workflows. This is a team contribution to content infrastructure, rather than authorship of the entire public website.',stack:['TypeScript','Node.js','Contentful','GraphQL','AWS'],url:'https://www.lonelyplanet.com/'},
{id:'opticare',name:'Opticare',type:'Optical customer management',category:['platforms'],theme:'opticare',headline:'A clearer view of every customer.',summary:'Customer records, optical measurements and consultation information in one internal system.',role:'Full Stack Developer',context:'Optical service teams need to keep customer details, measurements and consultation records available throughout the service process.',contribution:'Built a customer information management system to register customers and store optical measurements and important service information. The supplied interface shows searchable customer records, export and record-management actions.',detail:'The work also includes support for the API and the application’s operational environment. The preview uses fictional data and does not reproduce customer information from the original screenshot.',stack:['Angular','Node.js','REST API'],caption:'Illustrative interface with fictional records. The original contains private customer information.'},
{id:'veomas',name:'Ópticas Veo Más',type:'Ecommerce & ERP integration',category:['web','automation'],theme:'veomas',headline:'Commerce connected to the business.',summary:'An ecommerce experience integrated with COMPROSA’s ERP environment.',role:'Full Stack Web Developer · COMPROSA',context:'The online store needs to connect with the company’s enterprise systems, bringing ecommerce into the wider business workflow.',contribution:'Developed ecommerce work with an integration to COMPROSA’s ERP. The broader COMPROSA experience includes Softland ERP and electronic invoicing integrations through APIs, MuleSoft, SQL Server stored procedures and C# ASP.NET.',detail:'Worked on automated financial data exchange and notifications, alongside Angular frontend and existing business applications.',stack:['ERP integration','Express.js','MuleSoft','SQL Server','ASP.NET'],url:'https://www.opticasveomas.com/'},
{id:'ingemann',name:'Ingemann Data',type:'Internal geospatial information system',category:['platforms','automation'],theme:'ingemann',headline:'Complex spatial data. A useful perspective.',summary:'An internal platform for managing, processing and visualizing geospatial and agroclimatic information.',role:'Senior Full Stack Developer',context:'Geospatial and agroclimatic teams work with large spatial datasets and processing tasks that benefit from connected internal tools.',contribution:'Built internal geospatial information systems with Angular and NestJS. Designed spatial data models, APIs, raster-processing and bulk-data workflows, and interactive map visualizations with Leaflet.',detail:'Optimized workflows for large spatial datasets and reduced manual GIS steps. The linked corporate website provides company context; this case concerns the internal platform.',stack:['Angular','NestJS','PostGIS','Google Earth Engine','Leaflet'],url:'https://ingemann.com.ni/',linkLabel:'Company website'},
{id:'trust',name:'Trust Correduría',type:'Website & insurance operations',category:['platforms','web'],theme:'trust',headline:'A digital foundation for insurance follow-up.',summary:'A corporate website and an evolving internal system for tracking insurance-related information and operations.',role:'Systems Manager / Full Stack Developer',context:'Insurance operations need both a public presence and internal tools to support consistent follow-up.',contribution:'Developed the website and implemented and improved an insurance tracking system. Built and maintained internal applications with Python, Django, PostgreSQL, React and TypeScript.',detail:'Managed AWS EC2 deployments and Linux / Windows infrastructure, alongside Mailgun and Twilio integrations for communication workflows.',stack:['Django','React','TypeScript','PostgreSQL','AWS'],url:'https://www.trustcorreduria.com/'},
{id:'brainlabs',name:'Brainlabs Media',type:'Website development · Astro',category:['web'],theme:'brainlabs',headline:'A web presence built with Astro.',summary:'Website implementation using Astro for Brainlabs Media.',role:'Web Developer',context:'A website project for Brainlabs Media.',contribution:'Implemented the website using Astro, bringing the project’s content and presentation into a web experience.',detail:'This case highlights the website implementation and framework used.',stack:['Astro','Web development'],url:'https://brainlabs-media.com/'}
];
function art(p){
if(p.id==='glasswing')return `<div class="gw-art"><span class="mini-label">PEOPLE. PURPOSE. PROGRESS.</span><b>Good things<br>happen <em>together.</em></b><img src="assets/glasswing-training.jpeg" alt="Glasswing volunteer training interface" loading="lazy"><span class="art-caption">VOLUNTEER JOURNEY ↗</span></div>`;
if(p.id==='lonelyplanet')return `<div class="lp-art"><span class="lp-logo">lonely planet<span>◯</span></span><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="lp-copy">A world of stories.<br><i>Connected by code.</i></div><span class="art-caption">CONTENT PLATFORM / ENGINEERING</span></div>`;
if(p.id==='opticare')return `<div class="op-art"><span class="mini-label">OPTICARE / CUSTOMER WORKSPACE</span><div class="mini-window"><div class="window-head"><b>◎ Opticare</b><span>Customer records</span></div><div class="patient-top"><span>Customer directory</span><b>+ New record</b></div><div class="patient-row muted"><span>Customer</span><span>Last visit</span><span>Record</span></div>${['Alex Morgan','Taylor Reed','Jordan Ellis','Casey Parker'].map((n,i)=>`<div class="patient-row"><span><i>${n[0]}</i>${n}</span><span>Oct ${10+i}, 2026</span><span>↗</span></div>`).join('')}<small>ILLUSTRATIVE PREVIEW · FICTIONAL RECORDS</small></div><span class="art-caption">CUSTOMER CARE, WITH CONTEXT.</span></div>`;
if(p.id==='veomas')return `<div class="veo-art"><span class="mini-label">ÓPTICAS VEO MÁS</span><div class="glasses"><i></i><i></i></div><b>A better view.<br><em>A connected store.</em></b><span class="art-caption">ECOMMERCE ↔ ERP</span></div>`;
if(p.id==='ingemann')return `<div class="geo-art"><div class="contours"></div><span class="mini-label">INGEMANN DATA / GEOSPATIAL SYSTEMS</span><div class="geo-point p1"></div><div class="geo-point p2"></div><div class="geo-point p3"></div><b>Grounded in data.<br><em>Built for insight.</em></b><span class="art-caption">SPATIAL DATA / INTERNAL PLATFORM</span></div>`;
if(p.id==='trust')return `<div class="trust-art"><span class="mini-label">TRUST CORREDURÍA</span><div class="trust-mark">t<span>↗</span></div><b>Confidence,<br><em>at every step.</em></b><span class="art-caption">WEBSITE + INSURANCE WORKFLOWS</span></div>`;
return `<div class="brain-art"><span class="mini-label">BRAINLABS MEDIA</span><div class="brain-shape">b<span>✳</span></div><b>Ideas, brought<br><em>to the browser.</em></b><span class="art-caption">BUILT WITH ASTRO ↗</span></div>`;
}
const grid=document.querySelector('#project-grid');
grid.innerHTML=projects.map((p,i)=>`<article class="project ${i===6?'last-project':''}" data-categories="${p.category.join(' ')}"><button class="project-open" data-project="${p.id}" aria-label="Read ${p.name} case study"><div class="project-art ${p.theme}">${art(p)}</div><div class="project-meta"><div><span class="project-type">${p.type}</span><h3>${p.name}</h3></div><span class="round-arrow">↗</span></div><p>${p.summary}</p><span class="read-case">Explore case study ↗</span></button></article>`).join('');
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('.project').forEach(card=>card.hidden=button.dataset.filter!=='all'&&!card.dataset.categories.split(' ').includes(button.dataset.filter));}));
const dialog=document.querySelector('#case-dialog');let lastTrigger;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{lastTrigger=button;const p=projects.find(p=>p.id===button.dataset.project);document.querySelector('#case-content').innerHTML=`<div class="eyebrow">SELECTED WORK / ${p.type}</div><h2 id="case-title">${p.name}</h2><p class="case-headline serif">${p.headline}</p><div class="case-role">${p.role}</div><div class="project-art case-art ${p.theme}">${art(p)}</div><div class="case-text"><h3>The context</h3><p>${p.context}</p><h3>My contribution</h3><p>${p.contribution}</p><h3>How it connects</h3><p>${p.detail}</p><div class="tags">${p.stack.map(s=>`<span>${s}</span>`).join('')}</div>${p.image?`<figure><img src="${p.image}" alt="Glasswing volunteer training steps and introductory videos" loading="lazy"><img src="${p.secondImage}" alt="Glasswing volunteer platform sign-in" loading="lazy"><figcaption>${p.caption}</figcaption></figure>`:p.caption?`<p class="project-note">${p.caption}</p>`:''}${p.url?`<a class="button dark" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.linkLabel||'Visit website'} ↗</a>`:''}<a class="case-contact text-link" href="mailto:s.arriaza95@gmail.com">Let's discuss a similar project ↗</a></div>`;dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus();});document.querySelector('#year').textContent=new Date().getFullYear();
